import xml.etree.ElementTree as ET

def upgrade_spring_boot_pom(pom_file_path: str, spring_boot_version: str, java_version: str, dependency_upgrades: dict[str, str]):
    # Parse the POM file
    tree = ET.parse(pom_file_path)
    root = tree.getroot()

    # Define namespace for Maven POM
    namespace = {'mvn': 'http://maven.apache.org/POM/4.0.0'}
    ET.register_namespace('', 'http://maven.apache.org/POM/4.0.0')
    ET.register_namespace('xsi', 'http://www.w3.org/2001/XMLSchema-instance')

    # Update parent Spring Boot version
    parent = root.find('mvn:parent', namespace)
    if parent is not None:
        version_elem = parent.find('mvn:version', namespace)
        if version_elem is not None:
            version_elem.text = spring_boot_version

    # Update Java version property
    properties = root.find('mvn:properties', namespace)
    if properties is not None:
        java_version_elem = properties.find('mvn:java.version', namespace)
        if java_version_elem is not None:
            java_version_elem.text = java_version

    # Update specific dependencies (e.g., JJWT)
    dependencies = root.find('mvn:dependencies', namespace)
    if dependencies is not None:
        for dep in dependencies.findall('mvn:dependency', namespace):
            artifact_id = dep.find('mvn:artifactId', namespace)
            if artifact_id is not None and artifact_id.text in dependency_upgrades:
                version_elem = dep.find('mvn:version', namespace)
                if version_elem is not None:
                    version_elem.text = dependency_upgrades[artifact_id.text]

            # Remove deprecated JAXB API (built-in to Java 21)
            if artifact_id is not None and artifact_id.text == 'jaxb-api':
                dependencies.remove(dep)

    # Write updated POM back to file
    tree.write(pom_file_path, encoding='UTF-8', xml_declaration=True)

import os
import re
from pathlib import Path
from typing import Dict, List

def migrate_javax_to_jakarta(source_dir: str, exclude_patterns: List[str] = None) -> Dict[str, int]:
    if exclude_patterns is None:
        exclude_patterns = []

    # Define javax to jakarta namespace mappings
    replacements = {
        r'import javax\.persistence\.(.*?);': r'import jakarta.persistence.\1;',
        r'import javax\.validation\.(.*?);': r'import jakarta.validation.\1;',
        r'import javax\.servlet\.(.*?);': r'import jakarta.servlet.\1;',
        r'import javax\.xml\.bind\.(.*?);': r'import jakarta.xml.bind.\1;',
    }

    # Statistics tracking
    stats = {
        'files_processed': 0,
        'files_modified': 0,
        'total_replacements': 0,
        'import_types': {
            'jakarta.persistence': 0,
            'jakarta.validation': 0,
            'jakarta.servlet': 0,
            'jakarta.xml.bind': 0,
        }
    }

    # Walk through all Java files in source directory
    source_path = Path(source_dir)
    for java_file in source_path.rglob('*.java'):
        # Skip excluded patterns
        if any(pattern in str(java_file) for pattern in exclude_patterns):
            continue

        stats['files_processed'] += 1
        file_modified = False

        # Read file content
        try:
            with open(java_file, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception:
            continue

        original_content = content

        # Apply each replacement pattern
        for pattern, replacement in replacements.items():
            matches = re.findall(pattern, content)
            if matches:
                content = re.sub(pattern, replacement, content)
                # Track replacement type
                if 'persistence' in replacement:
                    stats['import_types']['jakarta.persistence'] += len(matches)
                elif 'validation' in replacement:
                    stats['import_types']['jakarta.validation'] += len(matches)
                elif 'servlet' in replacement:
                    stats['import_types']['jakarta.servlet'] += len(matches)
                elif 'xml.bind' in replacement:
                    stats['import_types']['jakarta.xml.bind'] += len(matches)

                file_modified = True

        # Write back if modified
        if file_modified and content != original_content:
            stats['files_modified'] += 1
            stats['total_replacements'] += sum(len(re.findall(p, original_content)) for p in replacements.keys())

            with open(java_file, 'w', encoding='utf-8') as f:
                f.write(content)

