public static SecurityFilterChain securityFilterChain(HttpSecurity http, UserDetailsService userDetailsService) throws Exception {
    // Build authorization configuration using lambda DSL
    http.authorizeHttpRequests(auth -> auth
            .requestMatchers("POST", "/api/users").permitAll()
            .requestMatchers("/api/auth/**").permitAll()
            .requestMatchers("/h2-console/**").permitAll()
            .requestMatchers("/actuator/health").permitAll()
            .requestMatchers("/api/admin/**").hasRole("ADMIN")
            .anyRequest().authenticated()
        )
        // Configure stateless session management for JWT
        .sessionManagement(session -> session
            .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
        )
        // Disable CSRF for stateless APIs
        .csrf(csrf -> csrf.disable())
        // Configure exception handling for authentication failures
        .exceptionHandling(exception -> exception
            .authenticationEntryPoint((request, response, authException) -> {
                response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Unauthorized");
            })
        );

    // Set authentication provider with custom UserDetailsService
    http.authenticationProvider(daoAuthenticationProvider(userDetailsService));

